"""Clean-room psycopg AsyncConnection — connect must not be followed into _connect_gen."""

class AsyncConnection:
    @classmethod
    async def connect(cls, conninfo="", **kwargs):
        return await cls._connect_gen(conninfo)

    @classmethod
    async def _connect_gen(cls, conninfo):
        # Fake "blocking" leaf that would FP if followed through awaited async API.
        import time
        time.sleep(0.001)
        return cls()
